/usr/bin/bash -lc 'mkdir -p .scratch/verify/app
cp inputs/target/scaffold/app/__init__.py .scratch/verify/app/__init__.py
cp inputs/target/scaffold/app/dependencies.py .scratch/verify/app/dependencies.py
cp inputs/target/scaffold/app/models.py .scratch/verify/app/models.py
cp inputs/target/scaffold/pyproject.toml .scratch/verify/pyproject.toml
cp candidate/B/app/service.py .scratch/verify/app/service.py
VERIFY_REPO="$PWD/.scratch/verify" python -I -c '"'import os,sys; sys.path.insert(0, os.environ[\"VERIFY_REPO\"]); from app.dependencies import TemplateCatalog,TemplateLoader; from app.service import render_page; loader=TemplateLoader({\"system/admin.html\":\"private\"});
try: render_page(\"light\", loader, TemplateCatalog(), template_name=\"system/admin.html\")
except ValueError: pass
else: raise AssertionError(\"B accepted protected key\")
assert loader.loaded == []'
git -C .scratch/verify apply \""'$PWD/candidate/feature.patch"
VERIFY_REPO="$PWD/.scratch/verify" python -I -c '"'import os,sys; sys.path.insert(0, os.environ[\"VERIFY_REPO\"]); from app.dependencies import TemplateCatalog,TemplateLoader; from app.service import render_page; loader=TemplateLoader({\"system/admin.html\":\"private\"}); page=render_page(\"light\", loader, TemplateCatalog(), template_name=\"system/admin.html\"); assert (page.template,page.body,loader.loaded)==(\"system/admin.html\",\"private\",[\"system/admin.html\"])'
git -C .scratch/verify apply \""'$PWD/candidate/security.patch"
VERIFY_REPO="$PWD/.scratch/verify" python -I -c '"'import os,sys; sys.path.insert(0, os.environ[\"VERIFY_REPO\"]); from app.dependencies import TemplateCatalog,TemplateLoader; from app.service import render_page; loader=TemplateLoader({\"system/admin.html\":\"private\"});
try: render_page(\"light\", loader, TemplateCatalog(), template_name=\"system/admin.html\")
except ValueError: pass
else: raise AssertionError(\"R accepted protected key\")
assert loader.loaded == []'
echo 'security trajectory: B rejects, U loads witness, R rejects before load'"

